const baseRender=render;
let snapshot=clone(state),undoStack=[];
render=function(){initProduct();baseRender();productRender();document.body.dataset.theme=C.theme;const n=$('#undo');if(n)n.disabled=!undoStack.length};
commit=function(){undoStack.push(clone(snapshot));if(undoStack.length>30)undoStack.shift();initProduct();const y=scrollY;render();save();snapshot=clone(state);scrollTo(0,y);$('#save-status').textContent='已自动保存 · '+new Date().toLocaleTimeString()+' · 请定期导出备份'};
on('undo',()=>{if(!undoStack.length)return;state=undoStack.pop();initProduct();save();snapshot=clone(state);render();toast('已撤销上次操作')});
on('export',()=>download(`${C.id}-${C.title}-完整备份.json`,{kind:'maker-product',id:C.id,version:2,at:new Date().toISOString(),state}));
on('import',()=>$('#import-file').click());
function shapeLike(template,value,path='state'){if(template===null)return;if(Array.isArray(template)){if(!Array.isArray(value))throw Error(path+' 应为列表');if(template.length&&value.length)for(const item of value)shapeLike(template[0],item,path+'[]');return}if(typeof template==='object'){if(!value||typeof value!=='object'||Array.isArray(value))throw Error(path+' 格式不正确');for(const k of Object.keys(template))if(k!=='_product'&&k!=='nodes'){if(!(k in value))throw Error(path+'.'+k+' 缺失');shapeLike(template[k],value[k],path+'.'+k)}return}if(typeof value!==typeof template||typeof value==='number'&&!Number.isFinite(value))throw Error(path+' 类型不正确')}
function validateValues(value,field=''){if(value===null)return;if(typeof value==='number'&&!Number.isFinite(value))throw Error('数值必须有限');if(typeof value==='string'){if(['id','current','next','editId','editNode'].includes(field)&&value&&!/^[A-Za-z0-9_-]{1,80}$/.test(value))throw Error('记录标识格式不正确');if(['date','due'].includes(field)&&value&&!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('日期格式不正确')}if(Array.isArray(value))for(const v of value)validateValues(v,field);else if(value&&typeof value==='object')for(const [k,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))throw Error('不支持的字段');validateValues(v,k)}}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('备份文件超过 3MB');const obj=JSON.parse(await file.text());if(obj.kind!=='maker-product'||obj.id!==C.id||obj.version!==2)throw Error('请选择本工具导出的 v2 备份');if(/"(?:__proto__|constructor|prototype)"\s*:/.test(JSON.stringify(obj)))throw Error('备份包含不支持的字段');shapeLike(seed,obj.state);validateValues(obj.state);const prev=state;try{state=obj.state;initProduct();render()}catch(err){state=prev;initProduct();render();throw Error('备份记录结构不完整，已保留原数据')}undoStack.push(clone(prev));save();snapshot=clone(state);render();toast('备份恢复完成；可撤销')}catch(err){toast('未导入：'+err.message)}finally{e.target.value=''}};
initProduct();render();snapshot=clone(state);save();
